"""Static original-model comparison for geometry conversion QA; not an in-game mod."""
from pathlib import Path
import json
ROOT=Path(r'P:\AI\Codex\projects\black-rock-shooter-hd-retexture')
OUT=ROOT/'workspace/pgr_reference/viewer'
source=(OUT/'BRS_model_reference.html').read_text('utf-8')
pgr,_=json.JSONDecoder().raw_decode(source.split('const models=',1)[1])
psp=json.loads((ROOT/'workspace/model_port/psp_models.json').read_text('utf-8'))
for m in psp:
 m['meshes']=[x for x in m['meshes'] if x['texture_index']<5]
 for part in m['meshes']:
  part['uvs']=[u if i%2==0 else 1-u for i,u in enumerate(part['uvs'])]
 m['scope']='PSP 원본 구조 복원 · 이식 전'
for m in pgr:m['scope']='퍼니싱 원본 참고 · PSP 이식 전'
candidate_parts=json.loads((ROOT/'workspace/model_port/candidate_v1/candidate_decoded_geometry.json').read_text('utf-8'))[134:]
for p in candidate_parts:
 p['uvs']=[u if i%2==0 else 1-u for i,u in enumerate(p['uvs'])]
 p['name']=['Eye','Cloth','Zipper','Face','Hair','Body'][p['texture_index']-7]
candidate=dict(name='퍼니싱 → PSP 변환 후보',scope='PSP 파일에서 다시 읽은 형태 · 게임 검증 전',meshes=candidate_parts)
models=[pgr[0],*psp,pgr[1],candidate]
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>BRS 얼굴·의상 이식 준비</title><style>
*{box-sizing:border-box}body{margin:0;background:#111923;color:#e4edf6;font:15px 'Segoe UI','Malgun Gothic',sans-serif}header{display:flex;align-items:center;gap:10px;padding:16px 24px;border-bottom:1px solid #354658;flex-wrap:wrap}h1{font-size:19px;margin:0 auto 0 0}button,select{font:inherit;background:#203447;color:#e4edf6;border:1px solid #52728d;padding:8px 12px;border-radius:6px}button:hover{background:#36516b}#view{height:calc(100vh - 160px);min-height:400px;position:relative}canvas{display:block;touch-action:none}#status{position:absolute;top:15px;left:24px;color:#aec7db;pointer-events:none}footer{padding:13px 24px;line-height:1.65;font-size:13px;color:#aec0d2;border-top:1px solid #354658}</style>
<header><h1>BRS · 얼굴과 의상 비교</h1><select id="model"><option value="0">퍼니싱 기본 의상</option><option value="1">PSP 노멀 슈트</option><option value="2">PSP 부스터 유닛</option><option value="3">퍼니싱 추가 의상</option><option value="4" selected>PSP 변환 후보</option></select><button id="face">얼굴 확대</button><button id="full">전신</button><button id="front">앞</button><button id="back">뒤</button><button id="wire">구조 보기</button></header>
<div id="view"><div id="status"></div></div><footer><b>PSP 변환 후보와 양쪽 원본을 비교합니다. 게임 적용 결과는 아직 검증 전입니다.</b><br>드래그: 회전 · 휠: 확대 · Shift+드래그: 위치 이동. 원작의 조명·표정·애니메이션은 재현하지 않았습니다.</footer><script>'''
html+=(OUT/'three.min.js').read_text('utf-8')+'\n</script><script>const models='+json.dumps(models,separators=(',',':'))+';\n'
html+='''const host=document.querySelector('#view'),status=document.querySelector('#status'),renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor(0x182431);host.appendChild(renderer.domElement);const scene=new THREE.Scene(),cam=new THREE.PerspectiveCamera(32,1,.001,1000),loader=new THREE.TextureLoader();let group,angle=0,elev=.03,radius=3,target=new THREE.Vector3(),height=2,box,wire=false,faceMode=false;function focusFace(){faceMode=true;const model=models[+document.querySelector('#model').value];let face=group.children.find(x=>x.name.endsWith('Face'));if(face){let b=new THREE.Box3().setFromObject(face);b.getCenter(target);radius=b.getSize(new THREE.Vector3()).y*3.3}else{target.set(0,box.min.y+height*.91,(box.min.z+box.max.z)/2);radius=height*.43}angle=0;elev=0;}function full(){faceMode=false;box.getCenter(target);radius=height*2.2;angle=0;elev=.03}function loadModel(n){if(group){scene.remove(group);group.children.forEach(x=>{x.geometry.dispose();x.material.map.dispose();x.material.dispose()})}group=new THREE.Group();let m=models[n];for(const p of m.meshes){let g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p.positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(p.normals,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(p.uvs,2));if(p.colors)g.setAttribute('color',new THREE.Float32BufferAttribute(p.colors,4));g.setIndex(p.indices);let t=loader.load(p.texture);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;let blend=p.material_state?.df===0x32;let mat=new THREE.MeshBasicMaterial({map:t,side:p.cull?THREE.FrontSide:THREE.DoubleSide,transparent:blend,depthWrite:!blend,alphaTest:p.material_state?((p.material_state.c9&256)?((p.material_state.db>>8&255)/255):0):.15,wireframe:wire,vertexColors:!!p.colors});let o=new THREE.Mesh(g,mat);o.name=p.name;group.add(o)}scene.add(group);box=new THREE.Box3().setFromObject(group);height=box.getSize(new THREE.Vector3()).y;cam.near=height*.005;cam.far=height*20;cam.updateProjectionMatrix();let wantFace=faceMode;full();if(wantFace)focusFace();status.textContent=m.name+' · '+m.scope+' · '+m.meshes.reduce((a,x)=>a+x.indices.length/3,0).toLocaleString()+' 삼각형';}
function resize(){renderer.setSize(host.clientWidth,host.clientHeight);cam.aspect=host.clientWidth/host.clientHeight;cam.updateProjectionMatrix()}addEventListener('resize',resize);resize();loadModel(4);document.querySelector('#model').onchange=e=>loadModel(+e.target.value);document.querySelector('#face').onclick=focusFace;document.querySelector('#full').onclick=full;document.querySelector('#front').onclick=()=>{angle=0;elev=0};document.querySelector('#back').onclick=()=>{angle=Math.PI;elev=0};document.querySelector('#wire').onclick=()=>{wire=!wire;group.children.forEach(x=>x.material.wireframe=wire)};let drag=false,lx,ly;const c=renderer.domElement;c.onpointerdown=e=>{drag=true;lx=e.clientX;ly=e.clientY;c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;let dx=e.clientX-lx,dy=e.clientY-ly;if(e.shiftKey){target.y+=dy*radius*.001;target.x-=dx*radius*.001}else{angle-=dx*.008;elev=Math.max(-1.3,Math.min(1.3,elev+dy*.005))}lx=e.clientX;ly=e.clientY};c.onpointerup=()=>drag=false;c.onwheel=e=>{e.preventDefault();radius=Math.max(height*.06,Math.min(height*8,radius*Math.exp(e.deltaY*.001)))};function frame(){requestAnimationFrame(frame);cam.position.set(target.x+radius*Math.sin(angle)*Math.cos(elev),target.y+radius*Math.sin(elev),target.z+radius*Math.cos(angle)*Math.cos(elev));cam.lookAt(target);renderer.render(scene,cam)}frame();</script></html>'''
(OUT/'Model_port_preview.html').write_text(html,encoding='utf-8')
print('Viewer created:',OUT/'Model_port_preview.html')
